// Pick today's post: the latest one not yet posted.
// We use n8n static data to track which slugs we've already pushed.
const posts = $input.first().json.posts;
const staticData = $getWorkflowStaticData('global');
staticData.posted = staticData.posted ?? [];

const todays = posts.find(p => !staticData.posted.includes(p.slug));
if (!todays) {
  return [{ json: { skip: true, reason: 'no new posts' } }];
}
staticData.posted.push(todays.slug);
return [{ json: { ...todays, skip: false } }];

// Format LinkedIn post per VioX strategy:
// - hook on line 1 (first 2 lines visible above fold)
// - body with line breaks every 1-2 sentences
// - hashtags at end
// - link goes in FIRST COMMENT separately (best practice for organic reach)
const d = $input.first().json;
const li = d.linkedin;
const body = `${li.hook}\n\n${li.body}\n\n${li.cta}\n\n${li.hashtags.join(' ')}`;
return [{
  json: {
    linkedin_text: body,
    linkedin_first_comment: `Read the full piece → ${li.link}`,
    twitter_thread: d.twitter.thread,
    blog_url: li.link,
    og_image: $('Pick today\'s post').first().json.og_image,
  }
}];
